function accountCacheScope(email:string){
 let hashA=2166136261,hashB=5381;
 for(const char of email.trim().toLowerCase()){hashA=Math.imul(hashA^char.charCodeAt(0),16777619);hashB=Math.imul(hashB,33)^char.charCodeAt(0);}
 return `${(hashA>>>0).toString(16)}${(hashB>>>0).toString(16)}`;
}
