 const syncAttendanceChanges=useCallback(async()=>{
  if(!email||!org||!school)return 0;
  const key=attendanceSyncCursorKey(email,org,school);
  let cursor=await SecureStore.getItemAsync(key);
  let total=0;
  for(let pageNumber=0;pageNumber<10;pageNumber++){
   const query=cursor?`?limit=50&cursor=${encodeURIComponent(cursor)}`:"?limit=50";
   const page=await call(`/attendance/mobile-sync${query}`);
   const changes=Array.isArray(page.changes)?page.changes:[];
   if(changes.length){
    const changedSessions=changes.map((item:any)=>item.session).filter(Boolean) as Session[];
    setSessions(current=>{const map=new Map(current.map(item=>[item.id,item]));for(const item of changedSessions)map.set(item.id,item);return [...map.values()].sort((a,b)=>b.sessionDate.localeCompare(a.sessionDate));});
    setSelected(current=>current?changedSessions.find(item=>item.id===current.id)||current:current);
    const latestMarks=new Map<string,MarkStatus>();
    for(const change of changes)if(change.attendance?.studentId)latestMarks.set(change.attendance.studentId,change.attendance.status as MarkStatus);
    setRoster(current=>current.map(item=>latestMarks.has(item.student.id)?{...item,attendance:{status:latestMarks.get(item.student.id)!}}:item));
    total+=changes.length;
   }
   cursor=page.nextCursor||cursor;
   if(cursor)await SecureStore.setItemAsync(key,cursor);
   if(!page.hasMore)break;
  }
  const syncedAt=new Date().toISOString();setLastSyncAt(syncedAt);
  return total;
 },[email,org,school,call]);
